        self.myCanvas.after(self.delay, self.turn)

class Tile():
    """Represents a tile in the hexagonal grid"""
    def __init__(self, main, x, y):
        self.main = main
        self.x, self.y = x, y
        self.alive = False
        self.neighbors = []
        self.id = self.main.myCanvas.create_polygon(self.get_coords(), fill='white', outline='black')

    def get_coords(self):
        """Returns the coordinates for the hexagon"""
        x, y = self.x * XDIST + OFFSET, self.y * YDIST
        return [(x + dx, y + dy) for dx, dy in ltDELTAS]

    def isnear(self, tile):
        """Adds a neighbor to the tile"""
        self.neighbors.append(tile)

    def alivechance(self):
        """Randomly sets the tile to alive or dead"""
        self.alive = random.choice([True, False])
        self.update_color()

    def reset(self):
        """Resets the tile to dead"""
        self.alive = False
        self.update_color()

    def update(self):
        """Updates the tile based on the game of life rules"""
        alive_neighbors = sum(1 for neighbor in self.neighbors if neighbor.alive)
        if self.alive:
            if alive_neighbors < 2 or alive_neighbors > 3:
                self.alive = False
        else:
            if alive_neighbors == 3:
                self.alive = True
        self.update_color()

    def update_color(self):
        """Updates the color of the tile based on its alive status"""
        color = 'green' if self.alive else 'white'
        self.main.myCanvas.itemconfig(self.id, fill=color)

